//! Port of `PhotoReview.Shell.Interop/Graphics/RenderingAdditions.cs` (94 lines, WP-15) and `DWriteAdditions.cs` (64 lines, WP-17),
//! baseline `d92d6aae`. Unit W8-11f.
//!
//! What the two C# files were: raw-vtable calls for the two methods the WP-13b declarations had left as `Reserved` placeholders
//! (`ID2D1RenderTarget::FillRoundedRectangle` slot 19, `IDWriteFactory::CreateEllipsisTrimmingSign` slot 20), the
//! `D2dRoundedRect` struct and a `GraphicsKernel32` class (`CloseHandle`, `WaitForSingleObjectEx`, high-resolution waitable timer).
//! In Rust the first two are generated by `windows-rs` (`D2D1_ROUNDED_RECT`, `FillRoundedRectangle`, `CreateEllipsisTrimmingSign`);
//! what is kept is the kernel32 part as RAII (`WaitableTimer`, `wait_for_handle`) and the two-step ellipsis trimming recipe.

use windows::Win32::Foundation::{HANDLE, WAIT_ABANDONED, WAIT_EVENT, WAIT_IO_COMPLETION, WAIT_OBJECT_0, WAIT_TIMEOUT};
use windows::Win32::Graphics::DirectWrite::{
    DWRITE_TRIMMING, DWRITE_TRIMMING_GRANULARITY_CHARACTER, IDWriteFactory, IDWriteInlineObject, IDWriteTextFormat,
    IDWriteTextLayout,
};
use windows::Win32::System::Threading::{
    CREATE_WAITABLE_TIMER_HIGH_RESOLUTION, CancelWaitableTimer, CreateWaitableTimerExW, SetWaitableTimer,
    TIMER_ALL_ACCESS, WaitForSingleObjectEx,
};
use windows::core::{Owned, PCWSTR};

use super::com::{GfxError, ResultExt};

/// Result of a wait (C# `WaitForSingleObjectEx` returned a raw `uint`; the renderer only compared it with `WaitObject0`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum WaitResult {
    /// `WAIT_OBJECT_0` (0): the object is signaled.
    Signaled,
    /// `WAIT_TIMEOUT` (0x102).
    Timeout,
    /// `WAIT_ABANDONED` (0x80).
    Abandoned,
    /// `WAIT_IO_COMPLETION` (0xC0): an alertable wait was ended by an APC.
    IoCompletion,
    /// `WAIT_FAILED` (0xFFFFFFFF) or any other value.
    Failed,
}

impl WaitResult {
    /// Maps the raw `WAIT_EVENT` value.
    #[must_use]
    pub fn from_raw(raw: u32) -> Self {
        match WAIT_EVENT(raw) {
            WAIT_OBJECT_0 => Self::Signaled,
            WAIT_TIMEOUT => Self::Timeout,
            WAIT_ABANDONED => Self::Abandoned,
            WAIT_IO_COMPLETION => Self::IoCompletion,
            // WAIT_FAILED and any value this module does not model.
            _ => Self::Failed,
        }
    }

    /// C# `result == GraphicsKernel32.WaitObject0`.
    #[must_use]
    pub fn is_signaled(self) -> bool {
        self == Self::Signaled
    }
}

/// C# `GraphicsKernel32.WaitForSingleObjectEx(handle, timeout, alertable)`. A null/invalid handle gives `Failed`, never a panic.
#[must_use]
pub fn wait_for_handle(handle: HANDLE, timeout_ms: u32, alertable: bool) -> WaitResult {
    // SAFETY: `WaitForSingleObjectEx` takes the handle by value and only reads it; an invalid or null handle is
    // reported as WAIT_FAILED, not as undefined behaviour. No pointers are passed.
    let raw = unsafe { WaitForSingleObjectEx(handle, timeout_ms, alertable) };
    WaitResult::from_raw(raw.0)
}

/// `SetWaitableTimer` due time for "in `interval_ms` milliseconds": `-(interval_ms as i64) * 10_000` (100 ns units, negative =
/// relative; C# `GpuKeepAlive.SleepInterval`). Negative input is treated as 0 and gives 0.
#[must_use]
pub fn relative_due_time_100ns(interval_ms: i64) -> i64 {
    if interval_ms <= 0 {
        return 0;
    }
    // `interval_ms > 0`, so the negation cannot overflow; the product saturates instead of wrapping for absurd inputs.
    interval_ms.saturating_neg().saturating_mul(10_000)
}

/// A waitable timer (C# `GraphicsKernel32.CreateWaitableTimerEx` + `SetWaitableTimer` + `CloseHandle`, used by `GpuKeepAlive`
/// and, in the host, by `TimerFrameClock`). Created high resolution when the OS allows it, else a normal one. Closed on drop.
/// Not `Send`-restricted by the OS, but the keep-warm thread owns its own timer: do not share one across threads.
#[derive(Debug)]
pub struct WaitableTimer {
    handle: Owned<HANDLE>,
    high_resolution: bool,
}

impl WaitableTimer {
    /// `CreateWaitableTimerExW(null, null, CREATE_WAITABLE_TIMER_HIGH_RESOLUTION, TIMER_ALL_ACCESS)`; when that fails (old Windows 10),
    /// the same call with flags 0. Both failing is `Err` (C# `GpuKeepAlive` then falls back to `Thread.Sleep`, C# `TimerFrameClock`
    /// throws `Win32Exception`: the caller decides).
    pub fn new() -> Result<Self, GfxError> {
        // SAFETY: no attributes and no name (null pointers are documented as allowed); the call returns a new handle that
        // nothing else owns, or an error.
        let high = unsafe {
            CreateWaitableTimerExW(
                None,
                PCWSTR::null(),
                CREATE_WAITABLE_TIMER_HIGH_RESOLUTION,
                TIMER_ALL_ACCESS.0,
            )
        };
        if let Ok(raw) = high {
            // SAFETY: `CreateWaitableTimerExW` returned a handle the caller must close; `Owned` becomes its only owner.
            let handle = unsafe { Owned::new(raw) };
            return Ok(Self {
                handle,
                high_resolution: true,
            });
        }
        // SAFETY: same as above, flags 0 (Windows 10 before 1803 rejects the high-resolution flag).
        let plain = unsafe { CreateWaitableTimerExW(None, PCWSTR::null(), 0, TIMER_ALL_ACCESS.0) };
        let raw = plain.gfx("CreateWaitableTimerExW")?;
        // SAFETY: as above, the handle is new and caller-closed.
        let handle = unsafe { Owned::new(raw) };
        Ok(Self {
            handle,
            high_resolution: false,
        })
    }

    /// `true` when the high-resolution flag was accepted.
    #[must_use]
    pub fn is_high_resolution(&self) -> bool {
        self.high_resolution
    }

    /// The raw handle (to wait on it in `MsgWaitForMultipleObjectsEx`); owned by `self`, do not close it.
    #[must_use]
    pub fn handle(&self) -> HANDLE {
        *self.handle
    }

    /// `SetWaitableTimer(handle, &due, period 0, no completion routine, resume false)`; `due_100ns` negative = relative, positive =
    /// absolute (`FILETIME` units), as the Win32 call. A failure is `Err` (C# returned `false`).
    pub fn set_due_100ns(&self, due_100ns: i64) -> Result<(), GfxError> {
        // SAFETY: `self.handle` is a live timer handle owned by `self`; `due_100ns` is a local that outlives the call; period 0,
        // no completion routine and no argument pointer.
        unsafe { SetWaitableTimer(*self.handle, &due_100ns, 0, None, None, false) }.gfx("SetWaitableTimer")
    }

    /// `set_due_100ns(relative_due_time_100ns(interval_ms))`: fire once in `interval_ms` ms (C# `GpuKeepAlive.SleepInterval`). A
    /// failure is `Err` and the caller sleeps with `std::thread::sleep` instead.
    pub fn set_relative_ms(&self, interval_ms: i64) -> Result<(), GfxError> {
        self.set_due_100ns(relative_due_time_100ns(interval_ms))
    }

    /// `CancelWaitableTimer(handle)` (host `TimerFrameClock.OnArmedChanged(false)`, which used `PendingKernel32.CancelWaitableTimer`).
    /// A signal that was already raised stays raised; the caller drops stale signals itself.
    pub fn cancel(&self) -> Result<(), GfxError> {
        // SAFETY: `self.handle` is a live timer handle owned by `self`; no pointers are passed.
        unsafe { CancelWaitableTimer(*self.handle) }.gfx("CancelWaitableTimer")
    }

    /// `wait_for_handle(self.handle(), timeout_ms, alertable)`.
    #[must_use]
    pub fn wait(&self, timeout_ms: u32, alertable: bool) -> WaitResult {
        wait_for_handle(self.handle(), timeout_ms, alertable)
    }
}

/// C# `DWriteRawCalls.CreateEllipsisTrimmingSign(factory, textFormat)`: the "..." inline object in the font of `format`
/// (an `IDWriteTextLayout` derefs to `&IDWriteTextFormat`). Without it DirectWrite only cuts the text, it draws no ellipsis.
/// The returned object is owned (C# returned a raw pointer the caller had to `Marshal.Release`); dropping it releases it.
pub fn create_ellipsis_trimming_sign(
    factory: &IDWriteFactory,
    format: &IDWriteTextFormat,
) -> Result<IDWriteInlineObject, GfxError> {
    // SAFETY: `factory` and `format` are live owned interfaces borrowed for the call, used on the calling (UI) thread; the result is an
    // owned interface.
    unsafe { factory.CreateEllipsisTrimmingSign(format) }.gfx("IDWriteFactory::CreateEllipsisTrimmingSign")
}

/// The recipe of `DWriteTextRenderer.Build` for `TextTrimming::CharacterEllipsis` (after the caller set `NoWrap`):
/// `create_ellipsis_trimming_sign(factory, layout)`, then `layout.SetTrimming(&DWRITE_TRIMMING { granularity:
/// DWRITE_TRIMMING_GRANULARITY_CHARACTER, delimiter: 0, delimiterCount: 0 }, &sign)`. The layout keeps its own reference to the sign,
/// so the local `sign` is dropped at the end (C# released it in `finally`).
pub fn set_character_ellipsis_trimming(factory: &IDWriteFactory, layout: &IDWriteTextLayout) -> Result<(), GfxError> {
    let sign = create_ellipsis_trimming_sign(factory, layout)?;
    let trimming = DWRITE_TRIMMING {
        granularity: DWRITE_TRIMMING_GRANULARITY_CHARACTER,
        delimiter: 0,
        delimiterCount: 0,
    };
    // SAFETY: `trimming` is a local that outlives the call; `layout` and `sign` are live owned interfaces; the layout takes its own
    // reference to `sign` (dropped here afterwards).
    unsafe { layout.SetTrimming(&trimming, &sign) }.gfx("IDWriteTextFormat::SetTrimming")
}
